/* Typed identity lookup, deliberately separate from reaction prediction. */
let chemicalLibraryResults=[],chemicalLibrarySelected=null,chemicalLibraryRequest=0;
function chemicalLibraryHtml(){return `<div class="chemical-library"><label for="chemicalQuery">Search chemical name or formula</label><div class="chemical-search-row"><input id="chemicalQuery" maxlength="120" placeholder="e.g. sodium chloride, aspirin, C₉H₈O₄" autocomplete="off"><select id="chemicalSearchMode" aria-label="Search by"><option value="name">Name</option><option value="formula">Exact molecular formula</option></select><button class="btn small" type="button" id="chemicalSearch">Search PubChem</button></div><p class="muted">Type to find bench reagents. Search PubChem for additional published compound records. Formula searches can return isomers and isotope-labelled records: select the intended identity. This is not a complete library of every published chemical.</p><div id="chemicalSearchStatus" role="status"></div><div id="chemicalResults" class="chemical-results"></div><div id="chemicalSelected"></div><details><summary>Enter an unlisted chemical manually</summary><label for="chemicalManualName">Chemical name<input id="chemicalManualName" maxlength="120"></label><label for="chemicalManualFormula">Formula (as published)<input id="chemicalManualFormula" maxlength="80"></label><button class="btn secondary small" type="button" id="chemicalManual">Create unverified identity</button><small>Manual entries have unverified identity, appearance and reactions. Simple ionic formulas can receive a conditional solubility prediction.</small></details><small><a href="https://pubchem.ncbi.nlm.nih.gov/docs/pug-rest" target="_blank" rel="noopener">PubChem identity-data service</a> · online lookup requires internet. Identity data do not validate reactions. Recognized ionic formulas can use the general solubility rules when mixed with another supported aqueous salt. <a href="https://openstax.org/books/chemistry-2e/pages/j-solubility-products" target="_blank" rel="noopener">Solubility constants</a></small></div>`;}
function chemicalQueryNormal(q){return String(q).trim().replace(/[₀-₉]/g,c=>'₀₁₂₃₄₅₆₇₈₉'.indexOf(c));}
function chemicalLocalMatches(q,mode){q=chemicalQueryNormal(q);if(q.length<2)return [];return reagents.map((r,i)=>({name:r[0],formula:benchFormula(r[1]),index:i,local:true,unmodelled:r[2]==='publicationCustom'})).filter(x=>mode==='formula'?x.formula===q:x.name.toLowerCase().includes(q.toLowerCase())).slice(0,20);}
function chemicalRenderResults(results){chemicalLibraryResults=results;const el=document.getElementById('chemicalResults');if(!el)return;el.innerHTML=results.map((x,i)=>`<button type="button" class="chemical-result" data-chemical-result="${i}"><b>${esc(x.name)}</b><span>${esc(x.formula)}${x.weight?' · '+esc(x.weight)+' g/mol':''}</span><small>${x.local?(x.unmodelled?'Saved custom identity':'Existing bench reagent · see reaction coverage'):(x.cid?'PubChem CID '+Number(x.cid)+' · identity record':'Manual identity · unverified')}</small></button>`).join('');}
async function chemicalGet(path,signal){const response=await fetch('https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/'+path,{signal,credentials:'omit',headers:{Accept:'application/json'}});if(!response.ok)throw Error(response.status===404?'No matching record was found. Check the name or case-sensitive molecular formula.':'The publication service is unavailable ('+response.status+'). Please retry later.');return response.json();}
async function chemicalSearchRemote(q,mode,signal){q=chemicalQueryNormal(q);if(q.length<2||q.length>120)throw Error('Enter a chemical name or formula of 2–120 characters.');let path;if(mode==='formula'){if(!/^[A-Za-z0-9()+\-]+$/.test(q))throw Error('Use a molecular formula, e.g. C9H8O4. Formula searches are case-sensitive.');const ids=await chemicalGet('fastformula/'+encodeURIComponent(q)+'/cids/JSON?MaxRecords=20',signal);const list=ids.IdentifierList?.CID;if(!Array.isArray(list)||!list.length)throw Error('No formula matches found.');path='cid/'+list.slice(0,20).join(',');}else path='name/'+encodeURIComponent(q);const data=await chemicalGet(path+'/property/Title,MolecularFormula,MolecularWeight/JSON',signal);const rows=data.PropertyTable?.Properties;if(!Array.isArray(rows)||!rows.length)throw Error('No compound identity data returned.');return rows.slice(0,20).filter(x=>Number.isInteger(x.CID)&&x.MolecularFormula).map(x=>({cid:x.CID,name:String(x.Title||'Compound '+x.CID).slice(0,200),formula:String(x.MolecularFormula).slice(0,120),weight:Number(x.MolecularWeight),local:false}));}
function chemicalSelect(i){const r=chemicalLibraryResults[i];if(!r)return;chemicalLibrarySelected=r;document.getElementById('chemicalSelected').innerHTML=`<div class="notice"><b>${esc(r.name)}</b> · ${esc(r.formula)}${r.cid?` · <a href="https://pubchem.ncbi.nlm.nih.gov/compound/${r.cid}" target="_blank" rel="noopener">PubChem record ↗</a>`:''}<p>${r.local&&!r.unmodelled?'Uses the existing reagent identity and audited reaction coverage.':(r.cid?'Published identity only.':'User-entered identity is unverified.')+' Recognized ionic formulas can use solubility rules. The stock tint is a display placeholder.'}</p><label for="chemicalPreparationC">Solution concentration (mol/L)<input id="chemicalPreparationC" type="number" min="0" step="any" placeholder="Enter your prepared molarity"></label><button class="btn small" type="button" id="chemicalUse">Use this reagent on the bench</button></div>`;document.getElementById('chemicalUse').onclick=chemicalUseSelected;}
function chemicalUseSelected(){const r=chemicalLibrarySelected,input=document.getElementById('chemicalPreparationC'),raw=input?.value.trim(),c=Number(raw);if(!r||raw===''||!Number.isFinite(c)||c<0){document.getElementById('chemicalSearchStatus').textContent='Enter a finite, nonnegative molarity for your prepared solution.';return;}let index=r.index;if(!r.local){const row=[r.name,r.formula,'publicationCustom','Custom reagents','#d9e3e5','appearance unmodelled',c,{cid:r.cid,manualId:r.manualId,molarMass:r.weight,source:r.cid?'PubChem':'user-entered, unverified'}];index=reagents.findIndex(x=>x[2]==='publicationCustom'&&(r.cid?x[7]?.cid===r.cid:x[7]?.manualId===r.manualId));if(index<0){reagents.push(row);index=reagents.length-1;}else reagents[index]=row;}for(const id of ['pourReagent','reagent']){const el=document.getElementById(id);if(el){el.innerHTML=reagentOptions();el.value=String(index);}}syncReagentPreviews();syncBenchReagentAmount();for(const [sid,cid] of [['pourReagent','pourConcentration'],['reagent','mixConcentration']]){benchSyncConcentration(sid,cid);const el=document.getElementById(cid);if(el&&!el.disabled)el.value=c;}apparatusPopupReagent=index;chemicalSaveImports();persistWorkspace();document.getElementById('chemicalSearchStatus').textContent=r.name+' selected. Choose a vessel, enter the measured volume and add it. The vessel popup will also select this reagent.';}
function chemicalSaveImports(){try{localStorage.setItem('simlab-publication-reagents-v1',JSON.stringify(reagents.filter(x=>x[2]==='publicationCustom')));}catch{}}
function chemicalRestoreImports(){try{const rows=JSON.parse(localStorage.getItem('simlab-publication-reagents-v1')||'[]');if(!Array.isArray(rows))return;for(const x of rows.slice(0,200)){if(!Array.isArray(x)||x[2]!=='publicationCustom'||!(Number.isInteger(x[7]?.cid)||typeof x[7]?.manualId==='string')||typeof x[0]!=='string'||typeof x[1]!=='string')continue;if(!reagents.some(r=>r[2]==='publicationCustom'&&(x[7].cid?r[7]?.cid===x[7].cid:r[7]?.manualId===x[7].manualId)))reagents.push(x);}}catch{}}
function chemicalLibraryBind(){if(page!=='bench'||!document.getElementById('chemicalQuery'))return;if(!chemicalLibraryBind.restored){chemicalRestoreImports();chemicalLibraryBind.restored=true;}const query=document.getElementById('chemicalQuery'),mode=document.getElementById('chemicalSearchMode'),status=document.getElementById('chemicalSearchStatus'),button=document.getElementById('chemicalSearch');document.getElementById('chemicalManual').onclick=()=>{const name=document.getElementById('chemicalManualName').value.trim(),formula=chemicalQueryNormal(document.getElementById('chemicalManualFormula').value);if(!name||!formula){status.textContent='Enter both a name and formula.';return;}chemicalRenderResults([{name,formula,manualId:'manual-'+Date.now().toString(36),local:false}]);chemicalSelect(0);status.textContent='Unverified manual identity. Enter the prepared solution concentration to use it.';};const local=()=>{chemicalLibraryRequest++;chemicalLibrarySelected=null;document.getElementById('chemicalSelected').innerHTML='';chemicalRenderResults(chemicalLocalMatches(query.value,mode.value));status.textContent=chemicalQueryNormal(query.value).length<2?'Type at least two characters to show matches.':'Bench matches shown. Search PubChem for additional identities.';};query.oninput=local;mode.onchange=local;button.onclick=async()=>{const request=++chemicalLibraryRequest,q=query.value,m=mode.value,controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);button.disabled=true;status.textContent='Searching published compound identities…';try{const rows=await chemicalSearchRemote(q,m,controller.signal);if(request!==chemicalLibraryRequest)return;chemicalRenderResults(rows);status.textContent=rows.length+' PubChem identities shown (up to 20). Confirm the correct compound; formula alone does not identify an isomer.';}catch(e){if(request===chemicalLibraryRequest)status.textContent=e.name==='AbortError'?'Lookup timed out. Check internet access and retry.':e.message;}finally{clearTimeout(timeout);button.disabled=false;}};query.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();button.click();}};document.getElementById('chemicalResults').onclick=e=>{const b=e.target.closest('[data-chemical-result]');if(b)chemicalSelect(Number(b.dataset.chemicalResult));};local();}
